mapper.select:
SELECT COALESCE(g.group_idx, s.hero_idx) AS group_idx, h2.name_eng AS group_name_eng, h2.name_kor AS group_name_kor, c2.name AS ctp_name, c2.color AS color, COUNT(*) AS use_cnt FROM SETTING s LEFT JOIN HERO_GROUP g ON s.hero_idx = g.hero_idx JOIN HERO h2 ON h2.id = COALESCE(g.group_idx, s.hero_idx) LEFT JOIN CTP c2 ON h2.ctp_id = c2.id
AND (s.infinity IS NULL OR s.infinity != 1)
AND c2.name IN
#{ctp}
GROUP BY COALESCE(g.group_idx, s.hero_idx), h2.name_eng, h2.name_kor, c2.name, c2.color ORDER BY ${orderBy}
